function seedNotices(){
  DB.notices = DB.notices || [];
  var seeds = [
    { key:'guide-lms', title:'[필독] 이룸편입 LMS 사용 방법 (화면 안내)', pinned:true, showOnCal:false,
      body:guideNoticeBody(),
      images:['login','menu','vod','player','exam','mobile','cal','board','grade'] },
    { key:'guide-class', title:'[필독] 수업 진행 방식 · 학습 루틴 안내', pinned:true, showOnCal:false,
      body:guideClassBody(), images:['cal'] },
    { key:'guide-roadmap', title:'[학습 가이드] 편입 영어 준비 로드맵 · 대학별 난이도', pinned:true, showOnCal:false,
      body:guideRoadmapBody(), images:['exam','grade'] },
    { key:'guide-faq', title:'자주 묻는 질문 (FAQ)', pinned:false, showOnCal:false,
      body:guideFaqBody(), images:[] }
  ];
  var GUIDE_VER = 7;
  var made = 0;
  seeds.forEach(function(sd){
    var old = acf(DB.notices).filter(function(n){ return n.sysKey === sd.key; })[0];
    if(old){
      /* 시스템 공지는 저장본이 손상돼도 항상 코드 원문으로 유지한다 */
      var freshImgs = (sd.images||[]).map(function(k){ return {key:k, url:GUIDE_IMG[k], cap:GUIDE_CAP[k]}; });
      if(old.title !== sd.title || old.body !== sd.body || (old.guideVer||0) !== GUIDE_VER
         || (old.images||[]).length !== freshImgs.length){
        old.title = sd.title; old.body = sd.body; old.pinned = sd.pinned; old.showOnCal = sd.showOnCal;
        old.images = freshImgs; old.guideVer = GUIDE_VER; old.by = '이룸편입'; old._u = Date.now(); made++;
      }
      return;
    }
    DB.notices.push({
      id: uid('nt'), sysKey: sd.key, title: sd.title, body: sd.body,
      date: todayStr(), pinned: sd.pinned, showOnCal: sd.showOnCal,
      files: [], images: (sd.images||[]).map(function(k){ return {key:k, url:GUIDE_IMG[k], cap:GUIDE_CAP[k]}; }),
      by: '이룸편입', system: true, guideVer: GUIDE_VER, createdAt: todayStr()
    });
    made++;
  });
  if(made) save();
  return made;
}
